// Imported only after the user's explicit model-download action.
let transcriber=null,busy=false;
self.onmessage=async event=>{const {type,audio,id}=event.data;if(busy)return;busy=true;try{if(type==='load'){const {pipeline,env}=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.0.0');env.allowLocalModels=false;env.backends.onnx.wasm.numThreads=1;transcriber=await pipeline('automatic-speech-recognition','Xenova/whisper-tiny',{dtype:'q8',progress_callback:p=>self.postMessage({type:'progress',status:p.status,file:p.file,progress:p.progress})});self.postMessage({type:'ready'})}else if(type==='transcribe'){if(!transcriber)throw Error('Model not loaded');const result=await transcriber(audio,{task:'transcribe',language:null,return_timestamps:false,max_new_tokens:192});self.postMessage({type:'result',id,text:result.text||''})}}catch(e){self.postMessage({type:'error',id,message:e.message||String(e)})}finally{busy=false}};
